<?php $uid=(int)$currentUser['id']; ?>
<section class="container section shop-page">
<?php if($page==='wishlist'):?><p class="eyebrow">YOUR PERSONAL EDIT</p><h1>Saved for later.</h1><?php $products=all('SELECT p.*,c.department FROM wishlist w JOIN products p ON p.id=w.product_id JOIN categories c ON c.id=p.category_id WHERE w.user_id=? AND p.active=1',[$uid]);if(!$products):?><div class="empty-state"><h2>Your wishlist is waiting.</h2><p>Save pieces you love with the heart button.</p><a class="btn" href="<?=e(url('catalog'))?>">Explore the collection</a></div><?php else:?><div class="product-grid"><?php foreach($products as $p)product_card($p);?></div><?php endif;?>
<?php elseif($page==='cart'||$page==='checkout'):
$rows=cart_rows($uid);$sub=cart_subtotal($rows);$shipping=$sub>=20000||!$rows?0:800;
?><p class="eyebrow">YOUR EVERYDAY, SELECTED</p><h1><?=$page==='cart'?'Your shopping bag.':'The final details.'?></h1><?php if(!$rows):?><div class="empty-state"><h2>A little room for something good.</h2><p>Your bag is empty.</p><a class="btn" href="<?=e(url('catalog'))?>">Find your everyday →</a></div><?php else:?><div class="checkout-layout"><div>
<?php if($page==='cart'):foreach($rows as $r):?><article class="cart-item"><a href="<?=e(url('product',['id'=>$r['product_id']]))?>"><img src="<?=e(safe_image($r['image']))?>" alt="<?=e($r['name'])?>"></a><div><a class="product-name" href="<?=e(url('product',['id'=>$r['product_id']]))?>"><?=e($r['name'])?></a><p><?=e($r['color'].' / '.$r['size'])?></p><p><?=money($r['price'])?></p><?php if(!$r['active']||$r['quantity']>$r['stock']):?><p class="error-text">This item is unavailable in the requested quantity. Update or remove it.</p><?php endif;?><form method="post" class="inline-form"><?=token()?><input type="hidden" name="action" value="cart_update"><input type="hidden" name="id" value="<?=$r['id']?>"><label>Quantity<input type="number" name="quantity" value="<?=$r['quantity']?>" min="1" max="99" required></label><button class="text-button">Update</button></form><form method="post"><?=token()?><input type="hidden" name="action" value="cart_delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-button muted">Remove</button></form></div><strong><?=money((float)$r['price']*$r['quantity'])?></strong></article><?php endforeach;?>
<?php else:
$_SESSION['checkout_key']??=bin2hex(random_bytes(32));$address=one('SELECT * FROM addresses WHERE user_id=? ORDER BY id LIMIT 1',[$uid]);
?><div class="notice info">Demonstration checkout. No real payment is taken. Do not enter bank or card information.</div><form method="post" class="form-grid" id="checkout-form"><?=token()?><input type="hidden" name="action" value="checkout"><input type="hidden" name="checkout_key" value="<?=e($_SESSION['checkout_key'])?>"><h2>Delivery details</h2><div class="two-col"><label>Recipient name<input name="recipient" value="<?=old('recipient',$address['recipient']??$currentUser['name'])?>" maxlength="100" required autocomplete="name"></label><label>Phone<input name="phone" value="<?=old('phone',$address['phone']??'')?>" maxlength="30" required autocomplete="tel"></label></div><label>Street address<input name="line1" value="<?=old('line1',$address['line1']??'')?>" maxlength="255" required autocomplete="street-address"></label><div class="two-col"><label>City<input name="city" value="<?=old('city',$address['city']??'')?>" maxlength="100" required autocomplete="address-level2"></label><label>Postcode<input name="postcode" pattern="[0-9]{5}" value="<?=old('postcode',$address['postcode']??'')?>" maxlength="5" required autocomplete="postal-code"></label></div><p>Country: Malaysia · Standard shipping</p><label>Simulated payment result<select name="payment_result"><option value="success">Approve demo payment</option value="failure">Decline demo payment — test error handling</option></select></label><button class="btn">Place demo order · <?=money(($sub+$shipping)/100)?></button></form><?php endif;?>
</div><aside class="order-summary"><p class="eyebrow">ORDER SUMMARY</p><?php if($page==='checkout'):foreach($rows as $r):?><p class="summary-line"><span><?=e($r['name'])?> × <?=$r['quantity']?></span><span><?=money((float)$r['price']*$r['quantity'])?></span></p><?php endforeach;endif;?><p class="summary-line"><span>Subtotal</span><span><?=money($sub/100)?></span></p><p class="summary-line"><span>Delivery</span><span><?=$shipping?money($shipping/100):'Complimentary'?></span></p><p class="summary-line summary-total"><span>Total</span><strong><?=money(($sub+$shipping)/100)?></strong></p><?php if($page==='cart'):?><a class="btn full" href="<?=e(url('checkout'))?>">Continue to checkout →</a><?php endif;?><a class="text-link" href="<?=e(url($page==='cart'?'catalog':'cart'))?>"><?=$page==='cart'?'Continue shopping':'Return to your bag'?></a><small>Prices in Malaysian Ringgit. Local assignment demo.</small></aside></div><?php endif;?>
<?php elseif($page==='orders'):?><p class="eyebrow">YOUR FORME</p><h1>Your orders.</h1><?php $orders=all('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$uid]);if(!$orders):?><div class="empty-state"><p>No orders yet.</p><a class="btn" href="<?=e(url('catalog'))?>">Explore the collection</a></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Order</th><th>Placed</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['reference'])?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><span class="badge"><?=e($o['status'])?></span></td><td><a href="<?=e(url('order',['id'=>$o['id']]))?>">View order →</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<?php elseif($page==='order'):
$o=one('SELECT * FROM orders WHERE id=? AND user_id=?',[(int)($_GET['id']??0),$uid]);if(!$o){http_response_code(404);echo '<h1>Order not found.</h1>';return;}
?><p class="eyebrow">THANK YOU FOR CHOOSING FORME</p><h1>Your everyday is on its way.</h1><div class="order-heading"><strong><?=e($o['reference'])?></strong><span class="badge"><?=e($o['status'])?></span><span><?=e($o['created_at'])?></span></div><div class="checkout-layout"><div><?php foreach(all('SELECT * FROM order_items WHERE order_id=?',[$o['id']]) as $r):?><article class="cart-item"><img src="<?=e(safe_image($r['image']))?>" alt="<?=e($r['name'])?>"><div><h3><?=e($r['name'])?></h3><p><?=e($r['color'].' / '.$r['size'])?></p><p>Quantity: <?=$r['quantity']?></p></div><strong><?=money((float)$r['unit_price']*$r['quantity'])?></strong></article><?php endforeach;?></div><aside class="order-summary"><h2>Order details</h2><p><?=e($o['recipient'])?><br><?=e($o['phone'])?><br><?=e($o['address'])?></p><p class="summary-line"><span>Subtotal</span><span><?=money($o['subtotal'])?></span></p><p class="summary-line"><span>Delivery</span><span><?=money($o['shipping'])?></span></p><p class="summary-line summary-total"><span>Total</span><strong><?=money($o['total'])?></strong></p><p class="notice info">Payment: simulated paid. No money was collected.</p><?php if(in_array($o['status'],['Confirmed','Processing'],true)):?><form method="post" data-confirm="Cancel this order? Its stock will be restored."><?=token()?><input type="hidden" name="action" value="cancel_order"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="btn btn-outline full">Cancel order</button></form><?php endif;?><a class="text-link" href="<?=e(url('orders'))?>">All orders →</a></aside></div>
<?php endif;?>
</section>
